387	static void unescape_tag(char *tag)
388	{
389		char *tmp;
390	
391		if (tag == NULL)
392			return;
393	
394		tmp = tag;
395		for (; *tmp != '\0'; tmp++, tag++) {
396			if (*tmp == '\\') {
397				tmp++;
398				switch (*tmp) {
399				case ':':
400					*tag = ';';
401					break;
402				case 'n':
403					*tag = '\n';
404					break;
405				case 'r':
406					*tag = '\r';
407					break;
408				case 's':
409					*tag = ' ';
410					break;
411				default:
412					*tag = *tmp;
413					break;
414				}
415			} else {
416				*tag = *tmp;
417			}
418		}
419		*tag = '\0';
