468	static char *irc_parse_prefix(char *line, char **nick, char **address, char **tags)
469	{
470		char *p;
471	
472		*nick = *address = *tags = NULL;
473	
474		/* ["@" <tags> SPACE] :<nick> [["!" <user>] "@" <host>] SPACE */
475	
476		if (*line == '@') {
477			*tags = ++line;
478			while (*line != '\0' && *line != ' ') {
479				line++;
480			}
481			if (*line == ' ') {
482				*line++ = '\0';
483				while (*line == ' ') line++;
484			}
485		}
486	
487		if (*line != ':')
488			return line;
489	
490		*nick = ++line; p = NULL;
491		while (*line != '\0' && *line != ' ') {
492			if (*line == '!' || *line == '@') {
493				p = line;
494				if (*line == '!')
495					break;
496			}
497			line++;
498		}
499	
500		if (p != NULL) {
501			line = p;
502			*line++ = '\0';
503			*address = line;
504			while (*line != '\0' && *line != ' ')
505				line++;
506		}
507	
508		if (*line == ' ') {
509			*line++ = '\0';
510			while (*line == ' ') line++;
511		}
512	
513		return line;
514	}
