712	static void event_connected(IRC_SERVER_REC *server, const char *data, const char *from)
713	{
714		char *params, *nick;
715	
716		g_return_if_fail(server != NULL);
717	
718		params = event_get_params(data, 1, &nick);
719	
720		if (g_strcmp0(server->nick, nick) != 0) {
721			/* nick changed unexpectedly .. connected via proxy, etc. */
722			g_free(server->nick);
723			server->nick = g_strdup(nick);
724		}
725	
726		/* set the server address */
727		g_free(server->real_address);
728		server->real_address = from == NULL ?
729			g_strdup(server->connrec->address) : /* shouldn't happen.. */
730			g_strdup(from);
731	
732		/* last welcome message found - commands can be sent to server now. */
733		server->connected = 1;
734		server->real_connect_time = time(NULL);
735	
736		/* let the queue send now that we are identified */
737		server->wait_cmd = g_get_real_time();
738	
739		if (server->connrec->usermode != NULL) {
740			/* Send the user mode, before the autosendcmd.
741			 * Do not pass this through cmd_mode because it
742			 * is not known whether the resulting MODE message
743			 * (if any) is the initial umode or a reply to this.
744			 */
745			irc_send_cmdv(server, "MODE %s %s", server->nick,
746					server->connrec->usermode);
747			g_free_not_null(server->wanted_usermode);
748			server->wanted_usermode = g_strdup(server->connrec->usermode);
749		}
750	
751		signal_emit("event connected", 1, server);
752		g_free(params);
753	}
