755	static void event_server_info(IRC_SERVER_REC *server, const char *data)
756	{
757		char *params, *ircd_version, *usermodes, *chanmodes;
758	
759		g_return_if_fail(server != NULL);
760	
761		params = event_get_params(data, 5, NULL, NULL, &ircd_version, &usermodes, &chanmodes);
762	
763		/* check if server understands I and e channel modes */
764		if (strchr(chanmodes, 'I') && strchr(chanmodes, 'e'))
765			server->emode_known = TRUE;
766	
767		/* save server version */
768		g_free_not_null(server->version);
769		server->version = g_strdup(ircd_version);
770	
771		g_free(params);
772	}
