774	static void parse_chanmodes(IRC_SERVER_REC *server, const char *sptr)
775	{
776		mode_func_t *modefuncs[] = {
777			modes_type_a,
778			modes_type_b,
779			modes_type_c,
780			modes_type_d
781		};
782		char **item, **chanmodes;
783		int i;
784	
785		chanmodes = g_strsplit(sptr, ",", 5); /* ignore extras */
786	
787		for (i = 0, item = chanmodes; *item != NULL && i < 4; item++, i++) {
788			unsigned char *p = (unsigned char*) *item;
789			while (*p != '\0') {
790				server->modes[(int)*p].func = modefuncs[i];
791				p++;
792			}
793		}
794	
795		g_strfreev(chanmodes);
796	}
