798	static void parse_prefix(IRC_SERVER_REC *server, const char *sptr)
799	{
800		const char *eptr;
801	
802		if (*sptr++ != '(')
803			return; /* Unknown prefix format */
804	
805		eptr = strchr(sptr, ')');
806		if (eptr == NULL)
807			return;
808	
809		eptr++;
810		while (*sptr != '\0' && *eptr != '\0' && *sptr != ')' && *eptr != ' ') {
811			server->modes[(int)(unsigned char) *sptr].func =
812				modes_type_prefix;
813			server->modes[(int)(unsigned char) *sptr].prefix = *eptr;
814			server->prefix[(int)(unsigned char) *eptr] = *sptr;
815			sptr++; eptr++;
816		}
817	}
