820	static void event_isupport(IRC_SERVER_REC *server, const char *data)
821	{
822		char **item, *sptr, *eptr;
823		char **isupport;
824		gpointer key, value;
825	
826		g_return_if_fail(server != NULL);
827	
828		server->isupport_sent = TRUE;
829	
830		sptr = strchr(data, ' ');
831		if (sptr == NULL)
832			return;
833		sptr++;
834	
835		isupport = g_strsplit(sptr, " ", -1);
836	
837		for(item = isupport; *item != NULL; item++) {
838			int removed = FALSE;
839	
840			if (**item == '\0')
841				continue;
842	
843			if (**item == ':')
844				break;
845	
846			sptr = strchr(*item, '=');
847			if (sptr != NULL) {
848				*sptr = '\0';
849				sptr++;
850			}
851	
852			eptr = *item;
853			if(*eptr == '-') {
854				removed = TRUE;
855				eptr++;
856			}
857	
858			key = value = NULL;
859			if (!g_hash_table_lookup_extended(server->isupport, eptr,
860							  &key, &value) && removed)
861				continue;
862	
863			g_hash_table_remove(server->isupport, eptr);
864			if (!removed) {
865				g_hash_table_insert(server->isupport, g_strdup(eptr),
866						    g_strdup(sptr != NULL ? sptr : ""));
867			}
868	
869			g_free(key);
870			g_free(value);
871		}
872		g_strfreev(isupport);
873		irc_server_init_isupport(server);
874	
875	}
