58	int irc_nickcmp_rfc1459(const char *m, const char *n)
59	{
60		while (*m != '\0' && *n != '\0') {
61			if (to_rfc1459(*m) != to_rfc1459(*n))
62				return -1;
63			m++; n++;
64		}
65		return *m == *n ? 0 : 1;
66	}
67	
68	int irc_nickcmp_ascii(const char *m, const char *n)
69	{
70		while (*m != '\0' && *n != '\0') {
71			if (to_ascii(*m) != to_ascii(*n))
72				return -1;
73			m++; n++;
74		}
75		return *m == *n ? 0 : 1;
76	}
