78	static void event_names_list(IRC_SERVER_REC *server, const char *data)
79	{
80		IRC_CHANNEL_REC *chanrec;
81		NICK_REC *rec;
82		char *params, *type, *channel, *names, *ptr, *host;
83	        int op, halfop, voice;
84		char prefixes[MAX_USER_PREFIXES+1];
85		const char *nick_flags, *nick_flag_cur, *nick_flag_op;
86	
87		g_return_if_fail(data != NULL);
88	
89		params = event_get_params(data, 4, NULL, &type, &channel, &names);
90	
91		chanrec = irc_channel_find(server, channel);
92		if (chanrec == NULL || chanrec->names_got) {
93			/* unknown channel / names list already read */
94			g_free(params);
95			return;
96		}
97		nick_flags = server->get_nick_flags(SERVER(server));
98		nick_flag_op = strchr(nick_flags, '@');
99	
100		/* type = '=' = public, '*' = private, '@' = secret.
101	
102		   This is actually pretty useless to check here, but at least we
103		   get to know if the channel is +p or +s a few seconds before
104		   we receive the MODE reply...
105	
106		   If the channel key is set, assume the channel is +k also until
107	           we know better, so parse_channel_modes() won't clear the key */
108		if (*type == '*') {
109			parse_channel_modes(chanrec, NULL,
110					    chanrec->key ? "+kp" : "+p", FALSE);
111		} else if (*type == '@') {
112			parse_channel_modes(chanrec, NULL,
113					    chanrec->key ? "+ks" : "+s", FALSE);
114		}
115	
116		while (*names != '\0') {
117			while (*names == ' ') names++;
118			ptr = names;
119			while (*names != '\0' && *names != ' ') names++;
120			if (*names != '\0') *names++ = '\0';
121	
122			/* some servers show ".@nick", there's also been talk about
123			   showing "@+nick" and since none of these chars are valid
124			   nick chars, just check them until a non-nickflag char is
125			   found. */
126			op = halfop = voice = FALSE;
127			prefixes[0] = '\0';
128			while (isnickflag(server, *ptr)) {
129				prefix_add(prefixes, *ptr, (SERVER_REC *) server);
130				switch (*ptr) {
131				case '@':
132	                                op = TRUE;
133	                                break;
134				case '%':
135	                                halfop = TRUE;
136	                                break;
137				case '+':
138	                                voice = TRUE;
139	                                break;
140				default:
141					/* If this flag is listed higher than op (in the
142					 * isupport PREFIX reply), then count this user
143					 * as an op. */
144					nick_flag_cur = strchr(nick_flags, *ptr);
145					if (nick_flag_cur && nick_flag_op && nick_flag_cur < nick_flag_op) {
146						op = TRUE;
147					}
148					break;
149				}
150	                        ptr++;
151			}
152	
153			host = strchr(ptr, '!');
154			if (host != NULL)
155				*host++ = '\0';
156	
157			if (nicklist_find((CHANNEL_REC *) chanrec, ptr) == NULL) {
158				rec = irc_nicklist_insert(chanrec, ptr, op, halfop,
159							  voice, FALSE, prefixes);
160				if (host != NULL)
161					nicklist_set_host(CHANNEL(chanrec), rec, host);
162			}
163		}
164	
165		g_free(params);
166	}
