168	static void event_end_of_names(IRC_SERVER_REC *server, const char *data)
169	{
170		char *params, *channel;
171		IRC_CHANNEL_REC *chanrec;
172		NICK_REC *ownnick;
173		int nicks;
174	
175		g_return_if_fail(server != NULL);
176	
177		params = event_get_params(data, 2, NULL, &channel);
178	
179		chanrec = irc_channel_find(server, channel);
180		if (chanrec != NULL && !chanrec->names_got) {
181			ownnick = nicklist_find(CHANNEL(chanrec), server->nick);
182			if (ownnick == NULL) {
183				/* stupid server - assume we have ops
184				   if channel is empty */
185				nicks = g_hash_table_size(chanrec->nicks);
186				ownnick = irc_nicklist_insert(chanrec, server->nick,
187							      nicks == 0, FALSE,
188							      FALSE, FALSE, NULL);
189			}
190			nicklist_set_own(CHANNEL(chanrec), ownnick);
191	                chanrec->chanop = chanrec->ownnick->op;
192			chanrec->names_got = TRUE;
193			signal_emit("channel joined", 1, chanrec);
194		}
195	
196		g_free(params);
197	}
