199	static void event_who(SERVER_REC *server, const char *data)
200	{
201		char *params, *nick, *channel, *user, *host, *stat, *realname, *hops;
202		CHANNEL_REC *chanrec;
203		NICK_REC *nickrec;
204	
205		g_return_if_fail(data != NULL);
206	
207		params = event_get_params(data, 8, NULL, &channel, &user, &host,
208					  NULL, &nick, &stat, &realname);
209	
210		/* get hop count */
211		hops = realname;
212		while (*realname != '\0' && *realname != ' ') realname++;
213		if (*realname == ' ')
214			*realname++ = '\0';
215	
216		/* update host, realname, hopcount */
217		chanrec = channel_find(server, channel);
218		nickrec = chanrec == NULL ? NULL :
219			nicklist_find(chanrec, nick);
220		if (nickrec != NULL) {
221			if (nickrec->host == NULL) {
222	                        char *str = g_strdup_printf("%s@%s", user, host);
223				nicklist_set_host(chanrec, nickrec, str);
224	                        g_free(str);
225			}
226			if (nickrec->realname == NULL)
227				nickrec->realname = g_strdup(realname);
228			sscanf(hops, "%d", &nickrec->hops);
229		}
230	
231		nicklist_update_flags(server, nick,
232				      strchr(stat, 'G') != NULL, /* gone */
233				      strchr(stat, '*') != NULL); /* ircop */
234	
235		g_free(params);
236	}
