216		/* update host, realname, hopcount */
217		chanrec = channel_find(server, channel);
218		nickrec = chanrec == NULL ? NULL :
219			nicklist_find(chanrec, nick);
220		if (nickrec != NULL) {
221			if (nickrec->host == NULL) {
222	                        char *str = g_strdup_printf("%s@%s", user, host);
223				nicklist_set_host(chanrec, nickrec, str);
224	                        g_free(str);
225			}
226			if (nickrec->realname == NULL)
227				nickrec->realname = g_strdup(realname);
228			sscanf(hops, "%d", &nickrec->hops);
229		}
230	
231		nicklist_update_flags(server, nick,
232				      strchr(stat, 'G') != NULL, /* gone */
233				      strchr(stat, '*') != NULL); /* ircop */
234	
235		g_free(params);
236	}
237	
238	static void event_whois(IRC_SERVER_REC *server, const char *data)
239	{
240		char *params, *nick, *realname;
241		GSList *nicks, *tmp;
242		NICK_REC *rec;
243	
244		g_return_if_fail(data != NULL);
245	
246		/* first remove the gone-flag, if user is gone
247		   it will be set later.. */
248		params = event_get_params(data, 6, NULL, &nick, NULL,
249					  NULL, NULL, &realname);
250	
251		nicks = nicklist_get_same(SERVER(server), nick);
252		for (tmp = nicks; tmp != NULL; tmp = tmp->next->next) {
253			rec = tmp->next->data;
254	
255			if (rec->realname == NULL)
256				rec->realname = g_strdup(realname);
257		}
258		g_slist_free(nicks);
259	
260		/* reset gone and ircop status, we'll handle them in the following
261		   WHOIS replies */
262		nicklist_update_flags(SERVER(server), nick, FALSE, FALSE);
263		g_free(params);
264	}
