266	static void event_whois_away(SERVER_REC *server, const char *data)
267	{
268		char *params, *nick, *awaymsg;
269	
270		g_return_if_fail(data != NULL);
271	
272		/* set user's gone flag.. */
273		params = event_get_params(data, 3, NULL, &nick, &awaymsg);
274		nicklist_update_flags(server, nick, TRUE, -1);
275		g_free(params);
276	}
