279	{
280		char *params, *nick;
281	
282		g_return_if_fail(data != NULL);
283	
284		/* set user's gone flag.. */
285		params = event_get_params(data, 2, &nick, NULL);
286		nicklist_update_flags(server, nick, TRUE, -1);
