314	static void event_nick_invalid(IRC_SERVER_REC *server, const char *data)
315	{
316		if (!server->connected)
317			/* we used to call server_disconnect but that crashes
318			   irssi because of undefined memory access. instead,
319			   indicate that the connection should be dropped and
320			   let the irc method to the clean-up. */
321			server->connection_lost = server->no_reconnect = TRUE;
322	}
323	
324	static void event_nick_in_use(IRC_SERVER_REC *server, const char *data)
325	{
326		char *str, *cmd, *params, *nick;
327		int n;
328		gboolean try_alternate_nick;
329	
330		g_return_if_fail(data != NULL);
331	
332		if (server->connected) {
333			/* Already connected, no need to handle this anymore. */
334			return;
335		}
336		
337		try_alternate_nick = g_ascii_strcasecmp(server->nick, server->connrec->nick) == 0 &&
338		    server->connrec->alternate_nick != NULL &&
339		    g_ascii_strcasecmp(server->connrec->alternate_nick, server->nick) != 0;
340	
341		params = event_get_params(data, 2, NULL, &nick);
342		if (g_ascii_strcasecmp(server->nick, nick) != 0) {
343			/* the server uses a nick different from the one we send */
344			g_free(server->nick);
345			server->nick = g_strdup(nick);
346		}
347		g_free(params);
348	
349		/* nick already in use - need to change it .. */
350		if (try_alternate_nick) {
351			/* first try, so try the alternative nick.. */
352			g_free(server->nick);
353			server->nick = g_strdup(server->connrec->alternate_nick);
354		}
355		else if (strlen(server->nick) < 9) {
356			/* keep adding '_' to end of nick.. */
357			str = g_strdup_printf("%s_", server->nick);
358			g_free(server->nick);
359			server->nick = str;
360		} else {
361			/* nick full, keep adding number at the end */
362			for (n = 8; n > 0; n--) {
363				if (server->nick[n] < '0' || server->nick[n] > '9') {
364					server->nick[n] = '1';
365					break;
366				}
367	
368				if (server->nick[n] < '9') {
369					server->nick[n]++;
370					break;
371				}
372				server->nick[n] = '0';
373			}
374		}
375	
376		cmd = g_strdup_printf("NICK %s", server->nick);
377		irc_send_cmd_now(server, cmd);
378		g_free(cmd);
379	}
