381	static void event_target_unavailable(IRC_SERVER_REC *server, const char *data)
382	{
383		char *params, *channel;
384	
385		g_return_if_fail(data != NULL);
386	
387		params = event_get_params(data, 2, NULL, &channel);
388		if (!server_ischannel(SERVER(server), channel)) {
389			/* nick is unavailable. */
390			event_nick_in_use(server, data);
391		}
392	
393		g_free(params);
394	}
395	
396	static void event_nick(IRC_SERVER_REC *server, const char *data,
397			       const char *orignick)
398	{
399		char *params, *nick;
400	
401		g_return_if_fail(data != NULL);
402		g_return_if_fail(orignick != NULL);
403	
404		params = event_get_params(data, 1, &nick);
405	
406		if (g_ascii_strcasecmp(orignick, server->nick) == 0) {
407			/* You changed your nick */
408			if (server->last_nick != NULL &&
409			    g_ascii_strcasecmp(server->last_nick, nick) == 0) {
410	                        /* changed with /NICK - keep it as wanted nick */
411				g_free(server->connrec->nick);
412				server->connrec->nick = g_strdup(nick);
413			}
414	
415			server_change_nick(SERVER(server), nick);
416		}
417	
418	        nicklist_rename(SERVER(server), orignick, nick);
419		g_free(params);
420	}
421	
422	static void event_userhost(SERVER_REC *server, const char *data)
423	{
424		char *params, *hosts, **phosts, **pos, *ptr;
425		int oper;
426	
427		g_return_if_fail(data != NULL);
428	
429		/* set user's gone flag.. */
430		params = event_get_params(data, 2, NULL, &hosts);
431	
432		phosts = g_strsplit(hosts, " ", -1);
433		for (pos = phosts; *pos != NULL; pos++) {
434			ptr = strchr(*pos, '=');
435			if (ptr == NULL || ptr == *pos) continue;
436			if (ptr[-1] == '*') {
437				ptr[-1] = '\0';
438				oper = 1;
439			} else
440				oper = 0;
441			*ptr++ = '\0';
442	
443			nicklist_update_flags(server, *pos, *ptr == '-', oper);
444		}
445		g_strfreev(phosts);
446		g_free(params);
447	}
448	
449	static void event_setname(SERVER_REC *server, const char *data, const char *nick, const char *address)
450	{
451		GSList *nicks, *tmp;
452		NICK_REC *rec;
453	
454		if (!IS_IRC_SERVER(server))
455			return;
456	
457		g_return_if_fail(nick != NULL);
458		g_return_if_fail(data != NULL);
459		if (*data == ':') data++;
460	
461		nicks = nicklist_get_same(server, nick);
462		for (tmp = nicks; tmp != NULL; tmp = tmp->next->next) {
463			rec = tmp->next->data;
464	
465			g_free(rec->realname);
466			rec->realname = g_strdup(data);
467		}
468		g_slist_free(nicks);
469	}
