471	static void event_away_notify(IRC_SERVER_REC *server, const char *data, const char *nick, const char *add)
472	{
473		char *params, *awaymsg;
474	
475		if (!IS_IRC_SERVER(server))
476			return;
477	
478		g_return_if_fail(nick != NULL);
479		g_return_if_fail(data != NULL);
480	
481		params = event_get_params(data, 1 | PARAM_FLAG_GETREST, &awaymsg);
482		nicklist_update_flags(SERVER(server), nick, *awaymsg != '\0', -1);
483		g_free(params);
484	}
