493	static const char *get_nick_flags(SERVER_REC *server)
494	{
495		IRC_SERVER_REC *irc_server = (IRC_SERVER_REC *) server;
496		const char *prefix =
497			g_hash_table_lookup(irc_server->isupport, "PREFIX");
498	
499		prefix = prefix == NULL ? NULL : strchr(prefix, ')');
500		return prefix == NULL ? "" : prefix+1;
501	}
