32	/* Massjoin support - really useful when trying to do things (like op/deop)
33	   to people after netjoins. It sends
34	   "massjoin #channel nick!user@host nick2!user@host ..." signals */
35	static void event_join(IRC_SERVER_REC *server, const char *data,
36			       const char *nick, const char *address)
37	{
38		char *params, *channel, *account, *realname, *ptr;
39		IRC_CHANNEL_REC *chanrec;
40		NICK_REC *nickrec;
41		GSList *nicks, *tmp;
42	
43		g_return_if_fail(data != NULL);
44	
45		if (g_ascii_strcasecmp(nick, server->nick) == 0) {
46			/* You joined, no need to do anything here */
47			return;
48		}
49	
50		params = event_get_params(data, 3, &channel, &account, &realname);
51	
52		ptr = strchr(channel, 7); /* ^G does something weird.. */
53		if (ptr != NULL) *ptr = '\0';
54	
55		/* find channel */
56		chanrec = irc_channel_find(server, channel);
57		if (chanrec == NULL) {
58			g_free(params);
59			return;
60		}
61	
62		/* check that the nick isn't already in nicklist. seems to happen
63		   sometimes (server desyncs or something?) */
64		nickrec = nicklist_find(CHANNEL(chanrec), nick);
65		if (nickrec != NULL) {
66			/* destroy the old record */
67			nicklist_remove(CHANNEL(chanrec), nickrec);
68		}
69	
70		/* add user to nicklist */
71		nickrec = irc_nicklist_insert(chanrec, nick, FALSE, FALSE, FALSE, TRUE, NULL);
72		if (*account != '\0' && g_strcmp0(nickrec->account, account) != 0) {
73			nicklist_set_account(CHANNEL(chanrec), nickrec, account);
74		}
75	
76	        nicklist_set_host(CHANNEL(chanrec), nickrec, address);
77	
78		if (chanrec->massjoins == 0) {
79			/* no nicks waiting in massjoin queue */
80			chanrec->massjoin_start = time(NULL);
81			chanrec->last_massjoins = 0;
82		}
83	
84		if (nickrec->realname == NULL) {
85			/* Check if user is already in some other channel,
86			   get the realname and other stuff from there */
87			nicks = nicklist_get_same(SERVER(server), nick);
88			for (tmp = nicks; tmp != NULL; tmp = tmp->next->next) {
89				NICK_REC *rec = tmp->next->data;
90	
91				if (rec->realname != NULL) {
92					nickrec->last_check = rec->last_check;
93					nickrec->realname = g_strdup(rec->realname);
94					nickrec->gone = rec->gone;
95					nickrec->serverop = rec->serverop;
96					break;
97				}
98			}
99			g_slist_free(nicks);
100		}
101	
102		if (*realname != '\0' && g_strcmp0(nickrec->realname, realname) != 0) {
103			g_free(nickrec->realname);
104			nickrec->realname = g_strdup(realname);
105		}
106	
107		chanrec->massjoins++;
108		g_free(params);
109	}
