245				/* quick join/kick after which it's useless to
246				   send nick in massjoin */
247				chanrec->massjoins--;
248			}
249			nicklist_remove(CHANNEL(chanrec), nickrec);
250		}
251	
252		g_free(params);
253	}
254	
255	static void massjoin_send_hash(gpointer key, NICK_REC *nick, GSList **list)
256	{
257		if (nick->send_massjoin) {
258			nick->send_massjoin = FALSE;
259			*list = g_slist_append(*list, nick);
260		}
261	}
262	
263	/* Send channel's massjoin list signal */
264	static void massjoin_send(IRC_CHANNEL_REC *channel)
265	{
266		GSList *list;
267	
268		list = NULL;
269		g_hash_table_foreach(channel->nicks, (GHFunc) massjoin_send_hash, &list);
270	
271		channel->massjoins = 0;
272		signal_emit("massjoin", 2, channel, list);
273		g_slist_free(list);
274	}
275	
276	static void server_check_massjoins(IRC_SERVER_REC *server, time_t max)
277	{
278		GSList *tmp;
279	
280		/*
281		   1) First time always save massjoin count to last_massjoins
282		   2) Next time check if there's been less than massjoin_max_joins
283		      (yes, the name is misleading..) joins since previous check.
284		        yes) send a massjoin signal and reset last_massjoin count
285		        no) unless we've waited for massjoin_max_wait seconds already,
286			    goto 2.
287	
288		   So, with single joins the massjoin signal is sent 1-2 seconds after
289		   the join.
290		*/
291	
292		/* Scan all channels through for massjoins */
293		for (tmp = server->channels; tmp != NULL; tmp = tmp->next) {
294			IRC_CHANNEL_REC *rec = tmp->data;
295	
296			if (!IS_IRC_CHANNEL(rec) || rec->massjoins <= 0)
297				continue;
298	
299			if (rec->massjoin_start < max || /* We've waited long enough */
300			    (rec->last_massjoins > 0 &&
301			     rec->massjoins-massjoin_max_joins < rec->last_massjoins)) { /* Less than x joins since last check */
302				/* send them */
303				massjoin_send(rec);
304			} else {
305				/* Wait for some more.. */
306				rec->last_massjoins = rec->massjoins;
307			}
308		}
309	
310	}
311	
312	static int sig_massjoin_timeout(void)
313	{
314		GSList *tmp;
315		time_t max;
316	
317		max = time(NULL)-settings_get_int("massjoin_max_wait");
318		for (tmp = servers; tmp != NULL; tmp = tmp->next) {
319			IRC_SERVER_REC *server = tmp->data;
320	
321	                if (IS_IRC_SERVER(server))
322				server_check_massjoins(server, max);
323		}
324	
325		return 1;
326	}
327	
328	static void read_settings(void)
329	{
330		massjoin_max_joins = settings_get_int("massjoin_max_joins");
331	}
332	
333	void massjoin_init(void)
334	{
335	        settings_add_int("misc", "massjoin_max_wait", 5000);
336	        settings_add_int("misc", "massjoin_max_joins", 3);
337		massjoin_tag = g_timeout_add(1000, (GSourceFunc) sig_massjoin_timeout, NULL);
338	
339		read_settings();
340		signal_add_first("event join", (SIGNAL_FUNC) event_join);
341		signal_add("event chghost", (SIGNAL_FUNC) event_chghost);
342		signal_add("event account", (SIGNAL_FUNC) event_account);
343		signal_add("event part", (SIGNAL_FUNC) event_part);
344		signal_add("event kick", (SIGNAL_FUNC) event_kick);
345		signal_add("event quit", (SIGNAL_FUNC) event_quit);
346		signal_add("setup changed", (SIGNAL_FUNC) read_settings);
347	}
348	
349	void massjoin_deinit(void)
350	{
351		g_source_remove(massjoin_tag);
352	
353		signal_remove("event join", (SIGNAL_FUNC) event_join);
354		signal_remove("event chghost", (SIGNAL_FUNC) event_chghost);
355		signal_remove("event account", (SIGNAL_FUNC) event_account);
356		signal_remove("event part", (SIGNAL_FUNC) event_part);
357		signal_remove("event kick", (SIGNAL_FUNC) event_kick);
358		signal_remove("event quit", (SIGNAL_FUNC) event_quit);
359		signal_remove("setup changed", (SIGNAL_FUNC) read_settings);
360	}
