132	 * continuation in the next chunk. If a message is exactly a multiple of 400 bytes,
133	 * there must be a blank message of "AUTHENTICATE +" to indicate the end.
134	 *
135	 * This function returns the fully reassembled and decoded AUTHENTICATION message if
136	 * completed or NULL if there are more messages expected.
137	 */
138	static gboolean sasl_reassemble_incoming(IRC_SERVER_REC *server, const char *fragment, GString **decoded)
139	{
140		GString *enc_req;
141		gsize fragment_len;
142	
143		fragment_len = strlen(fragment);
144	
145		/* Check if there is an existing fragment to prepend. */
146		if (server->sasl_buffer != NULL) {
147			if (g_strcmp0("+", fragment) == 0) {
148				enc_req = server->sasl_buffer;
149			} else {
150				enc_req = g_string_append_len(server->sasl_buffer, fragment, fragment_len);
151			}
152			server->sasl_buffer = NULL;
153		} else {
154			enc_req = g_string_new_len(fragment, fragment_len);
155		}
156	
157		/*
158		 * Fail authentication with this server. They have sent too much data.
159		 */
160		if (enc_req->len > AUTHENTICATE_MAX_SIZE) {
161			return FALSE;
162		}
163	
164		/*
165		 * If the the request is exactly the chunk size, this is a fragment
166		 * and more data is expected.
167		 */
168		if (fragment_len == AUTHENTICATE_CHUNK_SIZE) {
169			server->sasl_buffer = enc_req;
170			return TRUE;
171		}
172	
173		if (enc_req->len == 1 && *enc_req->str == '+') {
174			*decoded = g_string_new_len("", 0);
175		} else {
176			gsize dec_len;
177			gint state = 0;
178			guint save = 0;
179	
180			/* Since we're not going to use the enc_req GString anymore we
181			 * can perform the decoding in place. */
182			dec_len = g_base64_decode_step(enc_req->str, enc_req->len,
183						       (guchar *)enc_req->str,
184						       &state, &save);
185			/* A copy of the data is made when the GString is created. */
186			*decoded = g_string_new_len(enc_req->str, dec_len);
187		}
188	
189		g_string_free(enc_req, TRUE);
190		return TRUE;
191	}
192	
193	/*
194	 * Splits the response into appropriately sized chunks for the AUTHENTICATION
195	 * command to be sent to the IRC server. If |response| is NULL, then the empty
196	 * response is sent to the server.
197	 */
198	void sasl_send_response(IRC_SERVER_REC *server, GString *response)
199	{
200		char *enc;
201		size_t offset, enc_len, chunk_len;
202	
203		if (response == NULL) {
204			irc_send_cmdv(server, "AUTHENTICATE +");
205			return;
206		}
207	
208		enc = g_base64_encode((guchar *) response->str, response->len);
209		enc_len = strlen(enc);
210	
211		for (offset = 0; offset < enc_len; offset += AUTHENTICATE_CHUNK_SIZE) {
212			chunk_len = enc_len - offset;
213			if (chunk_len > AUTHENTICATE_CHUNK_SIZE)
214				chunk_len = AUTHENTICATE_CHUNK_SIZE;
215	
216			irc_send_cmdv(server, "AUTHENTICATE %.*s", (int) chunk_len, enc + offset);
217		}
218	
219		if (offset == enc_len) {
220			irc_send_cmdv(server, "AUTHENTICATE +");
221		}
222		g_free(enc);
223	}
224	
225	/*
226	 * Called when the incoming SASL request is completely received.
227	 */
228	static void sasl_step_complete(IRC_SERVER_REC *server, GString *data)
229	{
230		IRC_SERVER_CONNECT_REC *conn;
231		GString *resp;
232	
233		conn = server->connrec;
234	
235		switch (conn->sasl_mechanism) {
236			case SASL_MECHANISM_PLAIN:
237				/* At this point we assume that conn->sasl_{username, password} are non-NULL.
238				 * The PLAIN mechanism expects a NULL-separated string composed by the authorization identity, the
239				 * authentication identity and the password.
240				 * The authorization identity field is explicitly set to the user provided username.
241				 */
242	
243				resp = g_string_new(NULL);
244	
245				g_string_append(resp, conn->sasl_username);
246				g_string_append_c(resp, '\0');
247				g_string_append(resp, conn->sasl_username);
248				g_string_append_c(resp, '\0');
249				g_string_append(resp, conn->sasl_password);
250	
251				sasl_send_response(server, resp);
252				g_string_free(resp, TRUE);
253	
254				break;
255	
256			case SASL_MECHANISM_EXTERNAL:
257				/* Empty response */
258				sasl_send_response(server, NULL);
259				break;
260		}
261	}
262	
263	static void sasl_step_fail(IRC_SERVER_REC *server)
264	{
265		irc_send_cmd_now(server, "AUTHENTICATE *");
266		irc_cap_finish_negotiation(server);
267	
268		sasl_timeout_stop(server);
269	
270		signal_emit("server sasl failure", 2, server, "The server sent an invalid payload");
271	}
272	
273	static void sasl_step(IRC_SERVER_REC *server, const char *data, const char *from)
274	{
275		GString *req = NULL;
276	
277		sasl_timeout_stop(server);
278	
279		if (!sasl_reassemble_incoming(server, data, &req)) {
280			sasl_step_fail(server);
281			return;
282		}
283	
284		if (req != NULL) {
285			sasl_step_complete(server, req);
286			g_string_free(req, TRUE);
287		}
288	
289		/* We expect a response within a reasonable time */
290		server->sasl_timeout = g_timeout_add(SASL_TIMEOUT, (GSourceFunc) sasl_timeout, server);
291	}
292	
293	static void sasl_disconnected(IRC_SERVER_REC *server)
294	{
295		g_return_if_fail(server != NULL);
296	
297		if (!IS_IRC_SERVER(server)) {
298			return;
299		}
300	
301		sasl_timeout_stop(server);
302	}
303	
304	static void sig_sasl_over(IRC_SERVER_REC *server)
305	{
306		if (!IS_IRC_SERVER(server))
307			return;
308	
309		/* The negotiation has now been terminated, if we didn't manage to
310		 * authenticate successfully with the server just disconnect. */
311		if (!server->sasl_success &&
312		    server->connrec->sasl_mechanism != SASL_MECHANISM_NONE) {
313			if (server->cap_supported == NULL ||
314			    !g_hash_table_lookup_extended(server->cap_supported, "sasl", NULL, NULL)) {
315				signal_emit("server sasl failure", 2, server, "The server did not offer SASL");
316			}
317	
318			if (settings_get_bool("sasl_disconnect_on_failure")) {
319				/* We can't use server_disconnect() here because we'd end up
320				 * freeing the 'server' object and be guilty of a slew of UaF. */
321				server->connection_lost = TRUE;
322				/* By setting connection_lost we make sure the communication is
323				 * halted and when the control goes back to irc_parse_incoming
324				 * the server object is safely destroyed. */
325				signal_stop();
326			}
327		}
328	
329	}
330	
331	void sasl_init(void)
332	{
333		settings_add_bool("server", "sasl_disconnect_on_failure", TRUE);
334	
335		signal_add_first("event 001", (SIGNAL_FUNC) sig_sasl_over);
336		/* this event can get us connected on broken ircds, see irc-servers.c */
337		signal_add_first("event 375", (SIGNAL_FUNC) sig_sasl_over);
338		signal_add_first("server cap ack sasl", (SIGNAL_FUNC) sasl_start);
339		signal_add_first("server cap end", (SIGNAL_FUNC) sig_sasl_over);
340		signal_add_first("event authenticate", (SIGNAL_FUNC) sasl_step);
341		signal_add_first("event 903", (SIGNAL_FUNC) sasl_success);
342		signal_add_first("event 902", (SIGNAL_FUNC) sasl_fail);
343		signal_add_first("event 904", (SIGNAL_FUNC) sasl_fail);
344		signal_add_first("event 905", (SIGNAL_FUNC) sasl_fail);
345		signal_add_first("event 906", (SIGNAL_FUNC) sasl_fail);
346		signal_add_first("event 907", (SIGNAL_FUNC) sasl_already);
347		signal_add_first("server disconnected", (SIGNAL_FUNC) sasl_disconnected);
348	}
349	
350	void sasl_deinit(void)
351	{
352		signal_remove("event 001", (SIGNAL_FUNC) sig_sasl_over);
353		signal_remove("event 375", (SIGNAL_FUNC) sig_sasl_over);
354		signal_remove("server cap ack sasl", (SIGNAL_FUNC) sasl_start);
355		signal_remove("server cap end", (SIGNAL_FUNC) sig_sasl_over);
356		signal_remove("event authenticate", (SIGNAL_FUNC) sasl_step);
357		signal_remove("event 903", (SIGNAL_FUNC) sasl_success);
358		signal_remove("event 902", (SIGNAL_FUNC) sasl_fail);
359		signal_remove("event 904", (SIGNAL_FUNC) sasl_fail);
360		signal_remove("event 905", (SIGNAL_FUNC) sasl_fail);
361		signal_remove("event 906", (SIGNAL_FUNC) sasl_fail);
362		signal_remove("event 907", (SIGNAL_FUNC) sasl_already);
363		signal_remove("server disconnected", (SIGNAL_FUNC) sasl_disconnected);
364	}
