48	{
49		GSList *tmp;
50	
51		g_return_val_if_fail(ban != NULL, NULL);
52	
53		for (tmp = list; tmp != NULL; tmp = tmp->next) {
54			BAN_REC *rec = tmp->data;
55	
56			if (g_ascii_strcasecmp(rec->ban, ban) == 0)
57				return rec;
58		}
59	
60		return NULL;
61	}
62	
63	BAN_REC *banlist_add(IRC_CHANNEL_REC *channel, const char *ban,
64			     const char *nick, time_t time)
65	{
66		BAN_REC *rec;
67	
68		g_return_val_if_fail(channel != NULL, NULL);
69		g_return_val_if_fail(ban != NULL, NULL);
70	
71		rec = banlist_find(channel->banlist, ban);
72		if (rec != NULL) {
73			/* duplicate - ignore. some servers send duplicates
74			   for non-ops because they just replace the hostname with
75			   eg. "localhost"... */
76			return NULL;
77		}
78	
79		rec = g_new(BAN_REC, 1);
80		rec->ban = g_strdup(ban);
81		rec->setby = nick == NULL || *nick == '\0' ? NULL :
82			g_strdup(nick);
83		rec->time = time;
84	
85		channel->banlist = g_slist_append(channel->banlist, rec);
86	
87		signal_emit("ban new", 2, channel, rec);
88		return rec;
89	}
90	
91	void banlist_remove(IRC_CHANNEL_REC *channel, const char *ban, const char *nick)
92	{
93		BAN_REC *rec;
94	
95		g_return_if_fail(channel != NULL);
96		g_return_if_fail(ban != NULL);
97	
98		rec = banlist_find(channel->banlist, ban);
99		if (rec != NULL) {
100			signal_emit("ban remove", 3, channel, rec, nick);
101			ban_free(&channel->banlist, rec);
102		}
103	}
104	
105	static void channel_destroyed(IRC_CHANNEL_REC *channel)
106	{
107		if (!IS_IRC_CHANNEL(channel))
108	                return;
109	
110		banlist_free(channel->banlist);
111	}
112	
113	static void event_banlist(IRC_SERVER_REC *server, const char *data)
114	{
115		IRC_CHANNEL_REC *chanrec;
116		char *params, *channel, *ban, *setby, *tims;
117		time_t tim;
118	
119		g_return_if_fail(data != NULL);
120	
121		params = event_get_params(data, 5, NULL, &channel, &ban, &setby, &tims);
122		chanrec = irc_channel_find(server, channel);
123		if (chanrec != NULL) {
124			tim = (time_t) atol(tims);
125			banlist_add(chanrec, ban, setby, tim);
126		}
127		g_free(params);
128	}
129	
130	void mode_lists_init(void)
131	{
132		signal_add("channel destroyed", (SIGNAL_FUNC) channel_destroyed);
133	
134		signal_add("chanquery ban", (SIGNAL_FUNC) event_banlist);
135	}
136	
137	void mode_lists_deinit(void)
138	{
139		signal_remove("channel destroyed", (SIGNAL_FUNC) channel_destroyed);
140	
141		signal_remove("chanquery ban", (SIGNAL_FUNC) event_banlist);
142	}
